{"source":"def build_outline(lines):
    if isinstance(lines, bool) or not isinstance(lines, list):
        return {"error": "invalid input"}
    top = []
    stack = []
    for line in lines:
        if not isinstance(line, str):
            return {"error": "invalid input"}
        head = parse_heading(line)
        if head is None:
            continue
        title = head["title"].strip()
        if title == "":
            continue
        node = {"title": title, "level": head["level"], "children": []}
        while stack and stack[-1]["level"] >= node["level"]:
            stack.pop()
        if stack:
            stack[-1]["children"].append(node)
        else:
            top.append(node)
        stack.append(node)
    return top"}

{"source":"def query_sections(request):
    if not isinstance(request, dict):
        return {"error": "invalid query"}
    if "lines" not in request or "text" not in request:
        return {"error": "invalid query"}
    lines = request["lines"]
    text = request["text"]
    if not isinstance(text, str) or text == "":
        return {"error": "invalid query"}
    index = index_sections(lines)
    if isinstance(index, dict):
        return index
    matches = []
    for entry in index:
        if text in entry["title"]:
            matches.append({"number": entry["number"], "title": entry["title"]})
    return {"matches": matches}"}

{"source":"def normalize_batch(payload):
    if not isinstance(payload, dict):
        return "invalid"
    if "samples" not in payload or "dilution" not in payload:
        return "invalid"
    samples = payload["samples"]
    dilution = payload["dilution"]
    if not isinstance(samples, list) or len(samples) == 0:
        return "invalid"
    if isinstance(dilution, bool) or not isinstance(dilution, (int, float)) or not dilution > 0:
        return "invalid"
    dilution = float(dilution)
    out_samples = []
    total_mass = 0.0
    for entry in samples:
        cleaned = clean_sample(entry)
        if cleaned == "invalid":
            return "invalid"
        adj_conc = cleaned["conc"] * dilution
        mass = adj_conc * cleaned["vol"]
        out_samples.append({
            "id": cleaned["id"],
            "adj_conc": adj_conc,
            "mass": mass,
            "flag": cleaned["flag"],
            "group": cleaned["group"],
        })
        total_mass += mass
    return {"samples": out_samples, "total_mass": total_mass}"}

{"source":"def aggregate_run(run):
    if not isinstance(run, dict):
        return "invalid"
    if "samples" not in run or "dilution" not in run:
        return "invalid"
    include_flagged = run.get("include_flagged", False)
    if not isinstance(include_flagged, bool):
        return "invalid"
    normalized = normalize_batch({"samples": run["samples"], "dilution": run["dilution"]})
    if normalized == "invalid":
        return "invalid"
    groups = {}
    considered = 0
    for sample in normalized["samples"]:
        if sample["flag"] and not include_flagged:
            continue
        considered += 1
        name = sample["group"]
        if name not in groups:
            groups[name] = {"count": 0, "total_mass": 0.0, "conc_sum": 0.0}
        bucket = groups[name]
        bucket["count"] += 1
        bucket["total_mass"] += sample["mass"]
        bucket["conc_sum"] += sample["adj_conc"]
    out = []
    for name in sorted(groups):
        bucket = groups[name]
        out.append({
            "group": name,
            "count": bucket["count"],
            "total_mass": bucket["total_mass"],
            "mean_conc": bucket["conc_sum"] / bucket["count"],
        })
    return {"groups": out, "count": considered}"}

{"source":"def build_report(job):
    if not isinstance(job, dict):
        return "invalid"
    if "samples" not in job or "dilution" not in job or "title" not in job:
        return "invalid"
    title = job["title"]
    if not isinstance(title, str) or len(title) == 0:
        return "invalid"
    aggregates = aggregate_run({
        "samples": job["samples"],
        "dilution": job["dilution"],
        "include_flagged": True,
    })
    if aggregates == "invalid":
        return "invalid"
    groups = aggregates["groups"]
    grand_total = 0.0
    top_group = None
    top_mass = None
    for group in groups:
        grand_total += group["total_mass"]
        if top_mass is None or group["total_mass"] > top_mass:
            top_mass = group["total_mass"]
            top_group = group["group"]
    return {
        "title": title,
        "group_count": len(groups),
        "grand_total_mass": grand_total,
        "top_group": top_group,
