    }"}

{"source":"def summarize_movements(batch):
    if not isinstance(batch, list):
        return {"ok": False, "error": "batch must be a list"}
    items = {}
    total_in = 0
    total_out = 0
    index = 0
    for entry in batch:
        parsed = parse_movement(entry)
        if not parsed["ok"]:
            return {"ok": False, "error": "invalid movement at index " + str(index) + ": " + parsed["error"]}
        movement = parsed["movement"]
        name = movement["item"]
        if name not in items:
            items[name] = {"in": 0, "out": 0}
        items[name][movement["kind"]] += movement["qty"]
        if movement["kind"] == "in":
            total_in += movement["qty"]
        else:
            total_out += movement["qty"]
        index += 1
    report = {}
    for name in sorted(items):
        report[name] = {"in": items[name]["in"], "out": items[name]["out"], "net": items[name]["in"] - items[name]["out"]}
    return {"ok": True, "items": report, "total_in": total_in, "total_out": total_out, "count": index}"}

{"source":"def reconcile_stock(payload):
    if not isinstance(payload, dict):
        return {"ok": False, "error": "payload must contain opening, movements and optional allow_backorder only"}
    keys = set(payload.keys())
    if "opening" not in keys or "movements" not in keys:
        return {"ok": False, "error": "payload must contain opening, movements and optional allow_backorder only"}
    for key in keys:
        if key != "opening" and key != "movements" and key != "allow_backorder":
            return {"ok": False, "error": "payload must contain opening, movements and optional allow_backorder only"}
    opening = payload["opening"]
    if not isinstance(opening, dict):
        return {"ok": False, "error": "opening must map item names to nonnegative integers"}
    for name in opening:
        value = opening[name]
        if not isinstance(name, str) or not name.strip():
            return {"ok": False, "error": "opening must map item names to nonnegative integers"}
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            return {"ok": False, "error": "opening must map item names to nonnegative integers"}
    allowed = payload.get("allow_backorder", [])
    if not isinstance(allowed, list):
        return {"ok": False, "error": "allow_backorder must be a list of item names"}
    for name in allowed:
        if not isinstance(name, str) or not name.strip():
            return {"ok": False, "error": "allow_backorder must be a list of item names"}
    summary = summarize_movements(payload["movements"])
    if not summary["ok"]:
        return summary
    closing = {}
    for name in opening:
        closing[name] = opening[name]
    for name in summary["items"]:
        net = summary["items"][name]["net"]
        if name in closing:
            closing[name] += net
        else:
            closing[name] = net
    backorder = set(allowed)
    violators = []
    for name in closing:
        if closing[name] < 0 and name not in backorder:
            violators.append(name)
    if violators:
        first = sorted(violators)[0]
        return {"ok": False, "error": "negative closing balance", "item": first, "balance": closing[first]}
    return {"ok": True, "closing": closing, "total_in": summary["total_in"], "total_out": summary["total_out"]}"}

{"source":"def audit_inventory(payload):
    result = reconcile_stock(payload)
    if not result["ok"]:
        return result
    closing = result["closing"]
    shortages = []
    for name in closing:
        if closing[name] < 0:
            shortages.append(name)
    shortages = sorted(shortages)
    status = "clear"
    if shortages:
        status = "shortage"
    return {"ok": True, "closing": closing, "shortages": shortages, "shortage_count": len(shortages), "status": status, "total_in": result["total_in"], "total_out": result["total_out"]}"}

{"source":"def price_segment(segment):
    normalized = normalize_segment(segment)
    if normalized is None:
        return None
    base_by_mode = {"walk": 0, "bus": 140, "rail": 320}
    rate_by_mode = {"walk": 0, "bus": 12, "rail": 25}
    mode = normalized["mode"]
    raw = normalized["fare_cents"] + base_by_mode[mode] + rate_by_mode[mode] * normalized["minutes"]
    if normalized["minutes"] >= 60:
        quote_cents = (9 * raw + 5) // 10
    else:
        quote_cents = raw
    return {
        "mode": mode,
        "origin": normalized["origin"],
        "dest": normalized["dest"],
        "minutes": normalized["minutes"],
        "quote_cents": quote_cents,
    }
"}

{"source":"def combine_segments(segments):
    if not isinstance(segments, list) or len(segments) == 0:
        return None
    normalized_legs = []
    for segment in segments:
        leg = normalize_segment(segment)
        if leg is None:
            return None
        normalized_legs.append(leg)
    merged = []
    for leg in normalized_legs:
        if merged:
            last = merged[-1]
            if last["mode"] == leg["mode"] and last["dest"] == leg["origin"]:
                merged[-1] = {
                    "mode": last["mode"],
                    "origin": last["origin"],
                    "dest": leg["dest"],
                    "minutes": last["minutes"] + leg["minutes"],
                    "fare_cents": last["fare_cents"] + leg["fare_cents"],
                }
                continue
        merged.append(leg)
    total_minutes = 0
    total_fare = 0
    for leg in merged:
        total_minutes = total_minutes + leg["minutes"]
        total_fare = total_fare + leg["fare_cents"]
    return {
        "legs": merged,
        "leg_count": len(merged),
        "total_minutes": total_minutes,
        "total_fare_cents": total_fare,
    }
"}

{"source":"def build_itinerary(request):
    if not isinstance(request, dict):
        return None
    if set(request.keys()) != {"traveler", "segments"}:
        return None
    traveler = request["traveler"]
    if not isinstance(traveler, str) or traveler.strip() == "":
        return None
    combined = combine_segments(request["segments"])
    if combined is None:
        return None
    legs = []
    for leg in combined["legs"]:
        if legs:
            last = legs[-1]
            if last["dest"] == leg["origin"]:
                penalty = 0
                if last["mode"] != leg["mode"]:
                    penalty = 7
                legs[-1] = {
                    "mode": last["mode"],
                    "origin": last["origin"],
                    "dest": leg["dest"],
                    "minutes": last["minutes"] + leg["minutes"] + penalty,
                    "fare_cents": last["fare_cents"] + leg["fare_cents"],
                }
                continue
        legs.append(leg)
    total_minutes = 0
    quote_cents = 0
    for leg in legs:
        quote = price_segment(leg)
        if quote is None:
            return None
        quote_cents = quote_cents + quote["quote_cents"]
        total_minutes = total_minutes + leg["minutes"]
    return {
        "traveler": traveler,
        "leg_count": len(legs),
        "legs": legs,
        "total_minutes": total_minutes,
        "quote_cents": quote_cents,
    }
